mapper.select:
select grade_id, competition_series_id,stage_id,
(select competition_name from competition_main_info where
competition_id = (select competition_id from competition_series_info where competition_series_id = #{competitionSeriesId})) competition_name,
user_id,
(select user_name from competition_apply_info where competition_series_id  = #{competitionSeriesId}) user_name,
team_code,
(select team_name from team_manager_info where team_code = #{teamCode}) team_name,
ranks, is_award, awards_name,
certificate_url, analyse_result, score,awards_money,competition_track_name,group_classify,
create_by, create_time, update_by, update_time, version, del_flag, org_id
from user_grade_info

     and competition_series_id = #{competitionSeriesId}
     and stage_id = #{stageId}
     and user_id = #{userId}
     and team_code = #{teamCode}
     and ranks = #{ranks}
     and is_award = #{isAward}
     and awards_name like concat('%', #{awardsName}, '%')
     and certificate_url = #{certificateUrl}
     and analyse_result = #{analyseResult}
     and version = #{version}
     and org_id = #{orgId}

select awards_name 'awardsName', count(awards_name) as 'num' from user_grade_info
where is_award = '1' and competition_series_id = #{competitionSeriesId} and stage_id = #{stageId}
and competition_track_name = #{competitionTrackName} and group_classify = #{groupClassify}
group by awards_name order by awards_name

mapper.update:
update user_grade_info
is_award = CASE
WHEN grade_id = #{item.gradeId} THEN #{item.isAward}
ELSE is_award END,
awards_name = CASE
WHEN grade_id = #{item.gradeId} THEN #{item.awardsName}
ELSE awards_name END,
awards_money = CASE
WHEN grade_id = #{item.gradeId} THEN #{item.awardsMoney}
ELSE awards_money END,
update_time = NOW(), version = version + 1
WHERE grade_id IN
#{item.gradeId}
